// Do not edit this file as it will be overwritten if HAMR codegen is rerun

use crate::bridge::extern_c_api as extern_api;
use data::*;

use proptest::prelude::*;

/// container for component's incoming port values
pub struct PreStateContainer {
  pub api_apGuidance: FlightStack::ApGuidanceAndValidity,
  pub api_qualifiedAttitude: FlightStack::QualifiedAttitude
}

/// setter for component's incoming port values
pub fn put_concrete_inputs_container(container: PreStateContainer)
{
  put_apGuidance(container.api_apGuidance);
  put_qualifiedAttitude(container.api_qualifiedAttitude);
}

/// setter for component's incoming port values
pub fn put_concrete_inputs(
  apGuidance: FlightStack::ApGuidanceAndValidity,
  qualifiedAttitude: FlightStack::QualifiedAttitude)
{
  put_apGuidance(apGuidance);
  put_qualifiedAttitude(qualifiedAttitude);
}

/// setter for IN DataPort
pub fn put_apGuidance(value: FlightStack::ApGuidanceAndValidity)
{
  *extern_api::IN_apGuidance.lock().unwrap_or_else(|e| e.into_inner()) = Some(value)
}

/// setter for IN DataPort
pub fn put_qualifiedAttitude(value: FlightStack::QualifiedAttitude)
{
  *extern_api::IN_qualifiedAttitude.lock().unwrap_or_else(|e| e.into_inner()) = Some(value)
}

/// getter for OUT DataPort
pub fn get_proposedRates() -> FlightStack::ProposedActuatorRates
{
  return extern_api::OUT_proposedRates.lock().unwrap_or_else(|e| e.into_inner()).expect("Not expecting None")
}
